from pathlib import Path
import json,re,html,hashlib
from PIL import Image
P=Path(__file__).resolve().parent
(P/'output').mkdir(exist_ok=True);(P/'qa').mkdir(exist_ok=True)
photos={x['id']:x for x in json.loads((P/'photo_manifest.json').read_text(encoding='utf8'))}
used=set();pages=[];titles=[]
def esc(s):return html.escape(str(s),quote=True)
def plain(s):return html.unescape(re.sub('<[^>]+>','',s)).strip()
def author(d):return 'FDominec' if d['id']=='crystal' else ('M.M.Minderhoud (Michiel1972)' if d['id']=='fuse_photo' else plain(d['author_html']))
def photo(key,caption):
 d=photos[key];used.add(key)
 lic='<a href="'+esc(d['license_url'])+'">'+esc(d['license'])+'</a>' if d['license_url'] else esc(d['license'])
 return f'<figure><img class="real" src="{d["file"]}"/><figcaption><b>ภาพถ่ายจริง:</b> {esc(caption)}<br/>ภาพ: {esc(author(d))} / <a href="{esc(d["page_url"])}">Wikimedia Commons</a> / {lic}<br/>ใช้ภาพเต็ม ย่อขนาดในหน้าเอกสาร ไม่แก้ไฟล์ภาพ</figcaption></figure>'
def board(filename,box,caption):
 source=P.parent/'originals'/filename;w,h=Image.open(source).size;x,y,bw,bh=box
 return f'<figure><svg class="board" viewBox="{x} {y} {bw} {bh}" xmlns="http://www.w3.org/2000/svg"><image href="../originals/{filename}" x="0" y="0" width="{w}" height="{h}"/></svg><figcaption><b>ภาพจริงบนบอร์ด:</b> {esc(caption)}<br/>ภาพผู้ใช้ในโครงการ • แสดงเฉพาะบริเวณ ไม่แก้ไฟล์ต้นฉบับ • ยังไม่ยืนยันหน้าที่/ค่าของทุกชิ้นในภาพ</figcaption></figure>'
def wire(x1,y1,x2,y2):return f'<path d="M{x1},{y1} L{x2},{y2}" stroke="#173b50" stroke-width="5" fill="none"/>'
def t(x,y,s,size=27):return f'<text x="{x}" y="{y}" font-family="Leelawadee UI,Tahoma" font-size="{size}" fill="#173b50">{esc(s)}</text>'
def symbol(kind):
 a=['<svg class="symbol" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 600 245"><rect width="600" height="245" rx="16" fill="#edf4f8"/>']
 if kind in ['R','SHUNT','F']:
  a+=[wire(75,115,200,115),f'<rect x="200" y="80" width="190" height="70" fill="white" stroke="#173b50" stroke-width="5"/>',wire(390,115,525,115),t(240,63,kind,37)]
  if kind=='SHUNT':a+=[wire(215,150,215,190),wire(375,150,375,190),t(170,228,'sense + / sense −',23)]
  elif kind=='F':a+=[wire(200,115,390,115),t(135,210,'F ≠ R0 ≠ FB',27)]
  else:a+=[t(160,212,'หน่วย Ω • ขาหน้าที่ 2 ขา',27)]
 elif kind=='L':
  a+=[wire(65,120,175,120),'<path d="M175,120 C175,35 235,35 235,120 C235,35 295,35 295,120 C295,35 355,35 355,120 C355,35 415,35 415,120" fill="none" stroke="#173b50" stroke-width="5"/>',wire(415,120,535,120),t(250,205,'L • H / mH / µH')]
 elif kind in ['C','CP']:
  a+=[wire(75,115,270,115),wire(270,65,270,165),wire(320,65,320,165),wire(320,115,525,115),t(270,215,'C • F')]
  if kind=='CP':a+=[t(210,65,'+',37),t(90,35,'ตัวอย่าง C มีขั้ว',26)]
 elif kind in ['D','LED']:
  a+=[wire(80,125,235,125),'<path d="M235,75 L235,175 L335,125 Z M335,70 L335,180" fill="none" stroke="#173b50" stroke-width="5"/>',wire(335,125,520,125),t(160,220,'A'),t(375,220,'K / cathode')]
  if kind=='LED':a+=['<path d="M315,70 L390,25 M368,28 L390,25 L381,46 M355,90 L430,45 M408,48 L430,45 L421,66" fill="none" stroke="#c8740a" stroke-width="5"/>',t(40,35,'LED: ลูกศรแสงออก',24)]
 elif kind=='BJT':
  a+=[wire(80,125,235,125),wire(235,65,235,185),wire(235,90,355,35),wire(235,160,355,215),'<path d="M330,204 L305,203 L314,184 Z" fill="#173b50"/>',t(80,108,'B'),t(370,45,'C'),t(370,222,'E'),t(300,125,'NPN',32)]
 elif kind=='MOS':
  a+=[wire(70,120,215,120),wire(215,55,215,185),wire(265,55,265,185),wire(265,55,385,55),wire(385,55,385,20),wire(265,185,385,185),wire(385,185,385,225),t(75,95,'G'),t(410,40,'D'),t(410,225,'S'),t(300,125,'MOSFET',30),t(55,240,'ขาหน้าที่แบบย่อ ไม่ใช่ลำดับขาจริง',23)]
 elif kind=='X':
  a+=[wire(65,125,205,125),wire(205,70,205,180),'<rect x="240" y="60" width="110" height="130" fill="white" stroke="#173b50" stroke-width="5"/>',wire(385,70,385,180),wire(385,125,530,125),t(220,225,'X / Y • Hz')]
 elif kind=='GND':
  a+=[wire(300,45,300,125),wire(220,125,380,125),wire(245,150,355,150),wire(270,175,330,175),t(135,225,'GND ต้องพิสูจน์ reference')]
 else:
  a+=['<rect x="180" y="45" width="240" height="145" rx="8" fill="white" stroke="#173b50" stroke-width="5"/>',t(260,130,kind,40)]
  for y in [75,115,155]:a+=[wire(120,y,180,y),wire(420,y,480,y)]
  a+=[t(75,230,'ขาจริงต้องดู datasheet และด้านมอง',23)]
 return ''.join(a)+'</svg>'
def table(headers,rows):return '<table><thead><tr>'+''.join('<th>'+x+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(x)+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table>'
def page(title,content,tag='บทเรียน'):
 titles.append(title);pages.append('<section><div class="tag">คอร์ส ECU • '+tag+'</div><h1>'+title+'</h1>'+content+'</section>')
def card(title,kind,pic,function,read,test,limit,question,ref):
 content='<div class="visual"><div>'+pic+'</div><div>'+symbol(kind)+'<p class="small">สัญลักษณ์เพื่อเรียนหน้าที่ ไม่ใช่ผังขาหรือวงจรของ ECU เฉพาะรุ่น</p></div></div>'
 content+='<div class="twocol"><div><h2>ทำหน้าที่อะไร</h2><p>'+function+'</p></div><div><h2>อ่านอะไรบนตัว</h2><p>'+read+'</p></div></div>'
 content+='<h2>เริ่มวัดอย่างไร</h2><p>'+test+'</p><div class="highlight"><b>อย่าสรุปเกินผลวัด</b><p>'+limit+'</p></div><p class="task"><b>ลองตอบ:</b> '+question+'</p><p class="refs">หลักการ: '+ref+'</p>'
 page(title,content)

page('รู้จักอุปกรณ์บน ECU','<p class="subtitle">เอกสารประกอบการเรียน R • L • C และอุปกรณ์ที่ช่างต้องรู้</p><div class="coverphotos">'+photo('resistors','ตัวต้านทานแบบแท่ง')+photo('inductor','ขดลวดแกนวงแหวน')+photo('electrolytic','คาปาซิเตอร์หลายรูปแบบ')+'</div><h2>ดูรูปจริง → อ่านสัญลักษณ์ → เลือกวิธีวัด → บันทึกหลักฐาน</h2><p>สำหรับผู้เริ่มเรียนและช่างที่ต้องการจัดพื้นฐานก่อนอ่านวงจร เอกสารนี้ใช้ภาพถ่ายจริงของอุปกรณ์ชิ้นเดี่ยวและภาพจากกล่องที่ผู้เรียนส่ง ควบคู่ภาพสัญลักษณ์ที่วาดขึ้นเพื่ออธิบาย</p><div class="highlight"><b>ภาพตัวอย่างไม่ใช่อะไหล่ทดแทนที่แนะนำ</b><p>อุปกรณ์ชิ้นเดี่ยวบางรูปเป็นชิ้นสำหรับงานอิเล็กทรอนิกส์ทั่วไป ไม่ได้ยืนยันเกรดยานยนต์ เบอร์ที่ติดตั้งใน ECU หรือค่าที่ควรวัดของกล่องทั้ง 7 ใบ</p></div><p>มีแบบฝึกหัด ใบงานบันทึกผล และเฉลยแนวคิดท้ายเล่ม รูปภายนอกระบุผู้ถ่ายและสิทธิ์ใต้ภาพ ไม่มีภาพอุปกรณ์ที่สร้างด้วย AI</p>','เริ่มต้น')
page('อ่านตัวอักษรและหน่วยให้เป็น',table(['สัญลักษณ์บนบอร์ดที่อาจพบ','ชื่อ / หน่วย','จำไว้'],[['R','ตัวต้านทาน • Ω / kΩ / MΩ','R123 เป็นรหัสตำแหน่ง ไม่ใช่ค่า 123 Ω'],['L / FB','ตัวเหนี่ยวนำ / ferrite • H หรืออิมพีแดนซ์ตามความถี่','FB ไม่ควรถูกแทนด้วยลวดเพราะวัด DC ต่ำ'],['C','คาปาซิเตอร์ • F / µF / nF / pF','แรงดันทนไม่ใช่แรงดันที่ต้องพบ'],['D / ZD','ไดโอด / zener / protection','ชื่อและการตั้ง reference ต่างกันตามผู้ผลิต'],['Q / TR','ทรานซิสเตอร์ / ภาคสวิตช์','แพ็กเกจเหมือนกัน แต่เบอร์และขาอาจต่าง'],['U / IC','วงจรรวม','8 ขาไม่ได้แปลว่าเป็น EEPROM ทุกตัว'],['X / Y • F • CN / J','นาฬิกา • ฟิวส์ • ขั้วต่อ','ให้ตรวจผัง/BOM ประกอบชื่อที่เห็น']])+'<h2>แปลงหน่วยที่ใช้บ่อย</h2>'+table(['เท่ากัน','ตัวอย่าง'],[['1 kΩ = 1,000 Ω','4.7 kΩ = 4,700 Ω'],['1 MΩ = 1,000,000 Ω','0.1 MΩ = 100 kΩ'],['1 µF = 1,000 nF','0.1 µF = 100 nF'],['1 nF = 1,000 pF','10 nF = 10,000 pF'],['1 mH = 1,000 µH','0.1 mH = 100 µH'],['1 mΩ = 0.001 Ω','100 mΩ = 0.1 Ω']])+'<p class="task">ตัวอักษร M กับ m ต่างกันมาก อ่านหน่วยก่อนเทียบผลวัดทุกครั้ง ชื่อ reference เป็นเพียงคำใบ้ ต้องพิสูจน์อุปกรณ์จริง</p>')

card('R ตัวต้านทานแบบแท่ง','R',photo('resistors','R แบบ axial มีแถบสี ใช้สอนการแยกค่ากับ tolerance'),'จำกัดกระแส แบ่งแรงดัน และกำหนดไบอัส หน่วยโอห์ม ใช้ V = I × R ในเงื่อนไขของตัวต้านทาน','รหัส 4 แถบ: ตัวเลข 2 แถบ → ตัวคูณ → tolerance ตัวอย่างที่กำหนดเพื่อสอน น้ำตาล–ดำ–แดง–ทอง = 1 kΩ ±5% ไม่ได้อ้างว่าทุกตัวในภาพมีค่านี้','ถอดแหล่งจ่ายและจัดการประจุตกค้างตามวิธีที่ถูกต้อง แล้ววัด Ω บันทึกว่าวัดคาบอร์ดหรือแยกขา หากมีทางขนานค่าที่อ่านอาจไม่ใช่ค่า R ตัวเดียว','แถบสีไม่บอกกำลังวัตต์และความทนพัลส์ครบ ภาพถ่ายแสงเพี้ยนอาจอ่านสีผิด และค่า Ω ที่ดูปกติยังไม่พิสูจน์สภาพเมื่อร้อน/รับโหลด','ถ้า R 1 kΩ ±5% แบบอุดมคติ ช่วงค่าตาม tolerance คือเท่าไร?','Vishay Color Code • Fluke Resistance')
card('R แบบ SMD และการอ่านรหัส','R',photo('smd_resistor','R SMD ตัวอย่างที่เห็นรหัส 122; ไม่ใช่ค่าของ R บนกล่องอื่น'),'หน้าที่เหมือน R แบบแท่ง แต่ติดผิวแผงและมีขนาดเล็ก บางรุ่นไม่มีรหัสค่า','ระบบตัวเลข 3 หลัก: 103 = 10 × 10³ Ω = 10 kΩ, 472 = 4.7 kΩ, 122 = 1.2 kΩ ระบบที่ใช้ R แทนจุดทศนิยม: 4R7 = 4.7 Ω อย่าใช้กฎนี้กับอุปกรณ์ทุกชนิด','อ่านรหัสบนตัวแยกจาก Rxxx บนแผง แล้ววัด Ω เมื่อไม่มีไฟ หากค่าไม่ตรง ให้ตรวจทางขนานและระบบรหัสของผู้ผลิตก่อน','รหัส EIA-96 ใช้ตารางต่างออกไป 0/000 อาจเป็น jumper ตามรุ่น ไม่ใช่ฟิวส์แทนกันได้ และขนาด SMD ไม่รับรองกำลังวัตต์โดยลำพัง','103 กับ R103 ที่พิมพ์บนแผงให้ข้อมูลเหมือนกันหรือไม่?','State of the Art Part Marking • Vishay')
card('Shunt ตัวต้านทานวัดกระแส','SHUNT',board('ecu-001-2.png',(565,330,285,140),'กลุ่มที่เห็น marking R270 ต้องยืนยันชนิด/การต่อก่อนเรียกว่า shunt'),'เปลี่ยนกระแสเป็นแรงดันตกเล็กน้อยให้วงจรตรวจจับ ตัวอย่างคำนวณ I = 2 A และ R = 0.1 Ω จะได้ V = 0.2 V เป็นโจทย์ ไม่ใช่ค่ากล่องในภาพ','ถ้าระบบ marking ของผู้ผลิตใช้ R เป็นจุดทศนิยม R270 บนตัวอาจหมายถึง 0.270 Ω แต่ R270 บน silk อาจเป็นเลขตำแหน่ง ต้องแยกให้ถูก','DMM สองสายอาจรวมความต้านทานสายและหน้าสัมผัส ค่าต่ำมากควรใช้วิธีชดเชยหรือการวัด 4 สายตามความเหมาะสม การวัดแรงดันขณะมีไฟต้องมีวงจรและ reference ที่ยืนยัน','บี๊บไม่ได้แปลว่าช็อต ตัวต้านทานค่าต่ำที่ขาด/ค่าเปลี่ยนอาจทำให้การอ่านกระแสผิด แต่ห้ามสรุปจากรูปร่างหรือรหัสอย่างเดียว','เหตุใดการเอาค่าความต้านทานสายวัดไปรวมจึงผิดมากในงาน mΩ?','Vishay notation • กฎของโอห์ม / ตัวอย่างคำนวณ')
card('L ตัวเหนี่ยวนำและ ferrite bead','L',photo('inductor','ตัวเหนี่ยวนำแกนวงแหวน เห็นลวดจริง; ค่า µH ไม่อนุมานจากรูป'),'L เก็บพลังงานในสนามแม่เหล็ก ใช้แปลงไฟและกรอง หน่วย H / mH / µH ส่วน ferrite bead ใช้ลดรบกวนตามย่านความถี่ ต้องดูอิมพีแดนซ์ กระแส และ DCR','บางตัวระบุค่า/เบอร์ บางตัวไม่ระบุ รูปร่างปิดแกนหรือสีของแกนไม่ได้ยืนยันค่า ชิ้นส่วนสองขาคล้าย R อาจเป็น ferrite','ตรวจขาดด้วย Ω ได้ตามขั้นตอนที่ไม่มีไฟ แต่การวัด L ต้องใช้ LCR และเงื่อนไขความถี่/กระแสที่ตรงงาน ตรวจ datasheet เรื่อง saturation และ current rating เมื่อต้องเลือกทดแทน','DC ต่ำไม่พิสูจน์ว่าขดลวดไม่ช็อตรอบ และไม่ยืนยันการกรองความถี่สูง ห้ามบายพาส L/FB ด้วยลวดเพราะเห็นมิเตอร์บี๊บ','L กับ ferrite มีข้อกำหนดใดที่โหมด Ω ของ DMM ไม่บอก?','TI Ferrite Beads in Gate Drive Circuits')
card('C เซรามิกและ MLCC','C',photo('ceramic','C เซรามิกแบบจาน; MLCC บน ECU อาจเป็นสี่เหลี่ยมเล็กและไม่มีรหัส'),'เก็บประจุ บายพาสรบกวน และทำงานเป็นตัวกรองร่วมกับ R/L C เซรามิกหลายแบบไม่มีขั้ว แต่ต้องยืนยันชนิดก่อน','ตัวอย่างระบบรหัส C แบบ pF: 104 = 100,000 pF = 100 nF = 0.1 µF ไม่ใช้สูตรนี้กับ marking ทุกแบบ MLCC ที่ไม่พิมพ์ค่าต้องหา BOM/เอกสารหรือวัดอย่างเหมาะสม','ตรวจประจุตกค้างก่อนโหมด C/Ω แล้วแยกวงจรตามคู่มือเครื่องวัด บันทึกความถี่และระดับสัญญาณของ LCR หากใช้เปรียบเทียบผล','สี/ขนาดไม่บอกค่าความจุ ค่าของเซรามิกไดอิเล็กทริกสูงบางชนิดลดลงเมื่อมี DC bias ค่าวัดคาบอร์ดหรือค่า C อย่างเดียวไม่พิสูจน์การรั่ว/เสียทุกเงื่อนไข','ถ้าชิ้นไม่มี marking จะเลือกค่าแทนจากสีได้หรือไม่ เพราะอะไร?','Murata DC-bias FAQ • หลักหน่วยความจุ')
card('C อิเล็กโทรไลต์และขั้ว','CP',photo('electrolytic','C อิเล็กโทรไลต์หลายขนาดและรูปแบบ ต้องอ่านฉลากแต่ละตัว'),'ใช้เก็บประจุและลด ripple หลายชนิดมีขั้ว ต้องตรวจ polarity และเงื่อนไขของผู้ผลิตก่อนต่อกลับ','100 µF 25 V คือค่าความจุกับพิกัดแรงดันทน ไม่ได้แปลว่าจุดนั้นต้องมี 25 V เครื่องหมายขั้วอาจต่างกันระหว่างชนิด เช่น aluminium กับ tantalum จึงไม่ใช้กฎแถบเดียวกับทุก C','ตัดแหล่งพลังงาน คายประจุด้วยวิธีที่รองรับและตรวจแรงดันตกค้างก่อนวัด แยกขาหรือถอดตามวิธีเครื่องวัด ตรวจ C/ESR/leakage ตามความจำเป็น','ไม่บวมก็เสียได้ ค่าความจุปกติอย่างเดียวไม่ยืนยัน ESR หรือการทำงานร้อน/โหลด และรูปบวมไม่ได้บอกสาเหตุเสียทั้งระบบ','ตัวเลข 25 V บน C คือค่าที่สายแดงต้องอ่านเสมอหรือไม่?','Fluke Resistance/Capacitance • ข้อมูลชนิดผู้ผลิต')
card('D ไดโอด และรู้จัก TVS','D',photo('diode','ไดโอด 1N4007 ตามแหล่งภาพ แถบบนตัวอย่างใช้ชี้ด้าน cathode ไม่ใช่ TVS'),'ไดโอดใช้กำหนดทิศทางกระแส เรียงกระแส หรือช่วยคลายพลังงาน ส่วน TVS ใช้จำกัดแรงดันกระชากตามพิกัดของมัน','สัญลักษณ์ A = anode, K = cathode แถบบนไดโอดตัวอย่างสัมพันธ์กับด้าน K แต่ต้องตรวจชนิด/marking ไม่กำหนด breakdown จากสีหรือแพ็กเกจ','ใช้ diode mode บนวงจรไม่มีไฟ บันทึกทั้งสองทิศและสภาวะคาบอร์ด/แยกขา ค่า forward ขึ้นกับชนิด กระแสทดสอบ และอุณหภูมิ','ไม่มีเลข drop เดียวตัดสินทุก D; TVS แบบสองทิศอาจขึ้น OL ทั้งคู่บน DMM ปกติ ผลนี้ไม่ยืนยันว่าเสียหรือว่ายัง clamp ได้ตามพิกัด ห้ามแทน TVS ด้วยไดโอดทั่วไปจากรูปร่าง','ถ้า TVS สองทิศขึ้น OL ทั้งสองทิศ ต้องเปลี่ยนทันทีหรือยังขาดอะไร?','Fluke How to Test Diodes • datasheet ตรงชนิด')
card('LED ไดโอดเปล่งแสง','LED',photo('led','LED สีแดงตัวอย่าง ใช้สอนรูปร่าง ไม่ใช่หลักฐานว่ามีอยู่ในทุก ECU'),'เปล่งแสงเมื่อไบอัสตามเงื่อนไข ใช้เป็นไฟแสดงสถานะในวงจรฝึก/เครื่องมือ ไม่ใช่โหลดที่ต่อกับแหล่งจ่ายโดยไม่จำกัดกระแส','สัญลักษณ์ LED มีลูกศรแสงออก เครื่องหมายขาจริงต้องตรวจชนิดและ datasheet โดยเฉพาะขาที่ถูกตัดแล้ว ไม่ตัดสินจากความยาวอย่างเดียว','diode mode อาจทำให้ LED บางรุ่นติดจาง หากพิกัดมิเตอร์เพียงพอ อ่านคู่มือก่อน ผลไม่ติดไม่ได้พิสูจน์ว่าเสียทุกชนิด','แรงดัน forward ขึ้นกับสี วัสดุ และกระแสทดสอบ LED ไม่ใช่ TVS และไม่ควรถูกใช้แทนไดโอดในภาคขับตามความคล้าย','ทำไม LED จึงต้องมีการควบคุมหรือจำกัดกระแส?','Fluke Diode Test • ข้อมูลรุ่น LED')
card('Q ทรานซิสเตอร์ BJT','BJT',photo('bjt','BC547 ตัวอย่าง BJT รูปร่าง TO-92; ภาพ MOSFET ไม่ใช่ BJT'),'สวิตช์หรือขยายสัญญาณ มีขาหน้าที่ B = base, C = collector, E = emitter ตัวอย่างสัญลักษณ์ในหน้านี้เป็น NPN','อ่านเบอร์เต็ม ผู้ผลิต และด้านมองแพ็กเกจ ลำดับขา E/B/C ไม่เหมือนกันทุกรุ่น และชิ้น 3 ขาอาจเป็นอุปกรณ์ชนิดอื่น','เมื่อไม่มีไฟและรู้ pinout แล้ว ตรวจรอยต่อตามชนิดและตรวจความผิดปกติระหว่างขา บันทึกผลทั้งทิศทาง วงจรขนานหรืออุปกรณ์ป้องกันในตัวอาจเปลี่ยนผล','DMM ไม่รับรอง gain ทุกสภาวะ การรั่วเมื่อร้อน หรือการขับโหลดจริง อย่าเลือกอะไหล่จากจำนวนขา/ทรงเดียวกัน','แพ็กเกจ TO-92 บอกว่าเป็น BJT และขาซ้ายคือ E เสมอหรือไม่?','หลักทรานซิสเตอร์ • datasheet ของผู้ผลิตตรงเบอร์')
card('Q MOSFET และขา G D S','MOS',photo('mosfet','IRF630 ตัวอย่าง MOSFET แบบ TO-220 ไม่ใช่คำแนะนำแทนอะไหล่ ECU'),'ใช้ V_GS ควบคุมการนำระหว่าง drain/source; G = gate, D = drain, S = source ภาคขับจริงต้องทราบชนิดและ topology','ตรวจเบอร์และ datasheet ก่อน บางแพ็กเกจมีแท็บเชื่อมกับขาทางไฟฟ้า จึงไม่ถือเป็นกราวด์โดยอัตโนมัติ V_GS(th) ไม่ใช่ค่าที่รับรองเปิดนำเต็มโหลด','เมื่อรู้ชนิด/ขาแล้ว ตรวจรอยต่อ body diode และความผิดปกติตาม datasheet ในสภาพไม่มีไฟ อุปกรณ์ที่มีวงจรในตัวหรือทางขนานอาจให้ผลต่างจากแบบพื้นฐาน','DMM ไม่ยืนยัน R_DS(on) ที่เงื่อนไขโหลดจริง การรั่วเมื่อร้อน หรือสวิตช์ได้ถูกต้อง ต้องดูค่าขับ gate, gate charge และเงื่อนไขพิกัดของรุ่น ไม่ใช้แรงดัน gate เดียวกับทุกตัว','V_GS ต้องวัดจาก gate เทียบ source หรือเทียบตัวถังเสมอ?','ROHM MOSFET Basics • Vishay IRF630 datasheet')

page('IC หน้าตาเหมือนกัน หน้าที่ต่างกัน','<div class="visual">'+board('ecu-001-1.png',(235,335,195,180),'แพ็กเกจขาสี่ด้านจากกล่อง 01 ยังไม่ยืนยันหน้าที่')+photo('ic','ภาพ die ภายใน IC คนละชิ้นกับภาพบอร์ด ไม่ใช่ภาพแพ็กเกจหรือจุดวัด')+'</div>'+table(['ชนิดหน้าที่','ทำอะไร','ข้อห้ามเดา'],[['Regulator / power IC','สร้างและควบคุมไฟเลี้ยง','ไม่ใช้ 5 V เป็นคำตอบของทุกขา'],['Driver / interface','ขับโหลดหรือแปลงสัญญาณสื่อสาร','ตำแหน่งใกล้ปลั๊กยังไม่ยืนยันหน้าที่'],['MCU / processor','ประมวลผลและควบคุม','IC ใหญ่ไม่ได้เป็น MCU ทุกตัว'],['Memory','เก็บโปรแกรมหรือข้อมูล อาจอยู่ใน MCU','8 ขาไม่ได้เป็น EEPROM ทุกตัว']])+'<p class="highlight">อ่าน marking เต็ม โลโก้ แพ็กเกจ revision และเอกสารตรงรุ่นก่อนกำหนด VCC/GND/EN หรือขาสัญญาณ เครื่องหมายขา 1 ต้องเทียบด้านมองให้ถูก ห้ามจิ้ม die หรือลวดเชื่อมเพื่อหาไฟ</p><p class="task">กิจกรรม: เขียนข้อมูลที่ต้องมีเพิ่มก่อนยืนยันว่า IC หนึ่งตัวเป็น EEPROM</p>')
card('X Y คริสตัลและเรโซเนเตอร์','X',photo('crystal','ตัวอย่างคริสตัลหลายรูปแบบ ภาพต้นฉบับความละเอียดจำกัดจึงใช้ขนาดเล็ก'),'ช่วยกำหนดสัญญาณนาฬิกา หน่วย Hz / MHz คริสตัล resonator กับ oscillator ที่มีวงจรและไฟเลี้ยงในตัวเป็นคนละชนิด','อ่านเบอร์และความถี่เมื่อชัด พร้อมดูชนิด จำนวนขาและโหลดที่ต้องการ ไม่เดาความถี่จากทรงกระป๋อง','DMM ไม่ยืนยันความถี่หรือการเริ่มสั่น งาน scope ต้องเลือกโพรบและจุดวัดที่ไม่โหลดวงจรมากเกินไปตามข้อมูลวงจร','โพรบที่ capacitance สูงอาจเปลี่ยนพฤติกรรมจนหยุดสั่น ห้ามเลือกจุดจิ้มสุ่มขา MCU หรือจ่ายไฟเข้าตัวถัง','การไม่มีรูปคลื่นหลังวางโพรบ อาจเกิดจากเครื่องมือได้อย่างไร?','Tektronix ABCs of Probes • datasheet ตรงอุปกรณ์')
page('CN J ปลั๊ก ลายทองแดง และ via','<div class="visual">'+board('ecu-005-3.png',(100,580,930,245),'หน้าปลั๊กกล่อง 05 มีคราบ แต่ยังไม่ตัดสินสภาพไฟฟ้าจากภาพ')+board('ecu-005-2.png',(240,65,1020,300),'จุดบัดกรีปลั๊กด้านหลัง ภาพหมุนคนละทิศกับด้านหน้า')+'</div><h2>สิ่งที่ต้องรู้ก่อนตามขา</h2><p>ด้านมองหน้าขั้วต่อกับด้านบัดกรีอาจกลับทิศ ต้องใช้ร่องล็อก มุมตัวเรือน และเลขช่องที่ชัดเจนก่อนกำหนดขา เริ่มจากชื่อขาตามเอกสาร แล้วตาม copper/via ทีละช่วง</p><h2>ตรวจอะไรได้</h2><p>ตรวจขางอ บัดกรีร้าว และความต่อเนื่องเมื่อปลอดพลังงานตามขั้นตอน แต่เสียงบี๊บอาจผ่านทางขนาน/อุปกรณ์ ไม่ใช่หลักฐานว่าเป็นเส้นทองแดงเดียว ความต้านทานหน้าสัมผัสภายใต้โหลดต้องใช้วิธีและเครื่องมือที่ตรงงาน</p><div class="highlight">คราบ/เงาสะท้อนไม่พิสูจน์น้ำเข้า ไหม้ หรือช็อต ไม่ขูดสารเคลือบหรือเปลี่ยนสภาพก่อนเก็บภาพ และห้ามจ่ายไฟตามสีสายที่คนก่อนต่อเพิ่ม</div><p class="task">ให้ผู้เรียนระบุว่าในภาพมีข้อมูลพอจะนับเลขขาหรือยัง และต้องยืนยันอะไร</p>')
card('F ฟิวส์ กับ R0 และ FB','F',photo('fuse_photo','ตัวอย่างฟิวส์รถยนต์ภายนอก ไม่ใช่หลักฐานตำแหน่งฟิวส์บน ECU'),'ฟิวส์ทำหน้าที่ป้องกันกระแสตามเงื่อนไขของมัน ส่วน R0 ใช้เชื่อมวงจรและ FB ลดรบกวนตามความถี่ แม้วัด DC ต่ำเหมือนกันก็ทำหน้าที่ต่าง','อ่านชนิด เบอร์ กระแสพิกัดและข้อกำหนดการตัดของฟิวส์จากผู้ผลิต ไม่เลือกจากสีหรือขนาดอย่างเดียว โดยเฉพาะเมื่อไม่ทราบระบบสีของชนิดนั้น','ตัดไฟและแยกตามขั้นตอนก่อนตรวจ continuity ผลขาดต้องตรวจสาเหตุกระแสเกิน ไม่ใส่ฟิวส์พิกัดสูงขึ้นหรือบายพาสเพื่อให้ทำงาน','ไม่แทนฟิวส์ด้วย R0/ลวด และไม่แทน FB ด้วย R0 เพียงเพราะบี๊บ วัดต่ำไม่ได้แปลว่าเป็นฟิวส์หรือช็อต','ชิ้นสองขาที่บี๊บมีความเป็นไปได้อะไรบ้างนอกจากช็อต?','datasheet ของชิ้นที่เลือก • หลัก continuity')
page('GND และจุดอ้างอิงของการวัด','<div class="visual">'+board('ecu-004-2.png',(430,680,400,360),'ลายและรูยึดในภาพ ไม่ได้ยืนยันว่าเป็น GND')+'<div>'+symbol('GND')+'<p class="small">กราวด์สัญญาณ กราวด์กำลัง และตัวถังไม่จำเป็นต้องแทนกันได้ทุกจุด</p></div></div><h2>วัดแรงดันต้องบอกทั้งจุดแดงและจุดดำ</h2><p>แรงดันเป็นความต่างระหว่างสองจุด เปลี่ยน reference อาจได้เลขต่าง แม้สายแดงอยู่ที่เดิม ต้องยืนยันเน็ตของขาที่ต้องวัดก่อน ตัวถัง รูยึด แท็บกำลัง และขั้วลบ C ไม่เป็นกราวด์อ้างอิงทุกกรณี</p><h2>โหมด Ω กับแรงดันตกขณะโหลด</h2><p>continuity ในสภาพไม่มีไฟไม่บอกความสามารถรับกระแสของจุดต่อ การวัดแรงดันตกภายใต้โหลดเป็นงานอีกขั้น ต้องมี pinout โหลดและวิธีที่อนุมัติ ไม่ใช้เอกสารพื้นฐานนี้ต่อไฟให้กล่องไม่ทราบรุ่น</p><div class="highlight">กราวด์โพรบสโคปบางระบบผูกกับ earth ห้ามหนีบลงจุดสวิตชิ่งหรือยกกราวด์เครื่องเพื่อแก้ปัญหา ต้องเลือก probe/reference/rating ให้เหมาะสม</div><p class="refs">หลักการ: Tektronix ABCs of Probes</p>')
page('อ่าน datasheet และแพ็กเกจก่อนเลือกอะไหล่','<div class="visual">'+photo('bjt','แพ็กเกจเล็กสามขา ไม่ใช่คำยืนยันลำดับขาของทุกตัว')+photo('mosfet','แพ็กเกจมีแท็บโลหะ ไม่ถือว่าแท็บคือกราวด์')+'</div>'+table(['ต้องตรวจ','เหตุผล'],[['เบอร์เต็มและผู้ผลิต','เบอร์คล้ายกันหรือ suffix ต่างอาจมี pinout/พิกัดต่าง'],['แพ็กเกจและด้านมอง','แยก top view/bottom view และตำแหน่งขา 1'],['พิกัดกับเงื่อนไข','absolute maximum ไม่ใช่จุดทำงานที่แนะนำ'],['ความร้อน พัลส์ และโหลด','เลขกระแสตัวใหญ่ไม่รับรองใช้แทนในวงจร ECU ได้'],['คุณสมบัติสำคัญ','R: tolerance/pulse; C: ESR/ripple; L: saturation; Q: drive/charge'],['แหล่งเอกสาร','ตรวจจากผู้ผลิตและ revision ไม่ใช้ภาพร้านเพียงอย่างเดียว']])+'<p class="task">ถ้าอะไหล่ใหม่เสียบลงรูเดิมได้ ยังต้องตรวจอะไรอีกอย่างน้อย 3 ข้อ?</p>')
page('เลือกโหมดวัดให้ตรงคำถาม',table(['คำถาม','เครื่องมือ/โหมดที่เริ่มใช้','ยังพิสูจน์อะไรไม่ได้'],[['R ขาดหรือค่าเปลี่ยน?','Ω เมื่อปลอดพลังงาน','พิกัดพัลส์หรือสภาพร้อนทั้งหมด'],['C มีค่าประมาณเท่าไร?','Capacitance/LCR ตามเงื่อนไข','ESR/leakage/สภาพโหลดทั้งหมด'],['L ขาดหรือไม่?','Ω / LCR ตามคำถาม','บี๊บไม่บอกช็อตรอบหรือ saturation'],['D นำสองทิศผิดปกติหรือไม่?','Diode mode ทั้งสองทิศ','breakdown/clamp ที่พิกัดจริง'],['Q มีรอยต่อผิดปกติ?','Diode/Ω ตาม datasheet','การขับโหลดจริงหรือการรั่วเมื่อร้อน'],['มี DC ที่จุดนี้หรือไม่?','V และ reference ที่ยืนยัน','ค่าเฉลี่ยไม่แทน ripple/transient'],['สัญญาณนาฬิกาทำงานหรือไม่?','scope/probe ตามวงจร','DMM ไม่ยืนยันความถี่/การเริ่มสั่น']])+'<h2>ลำดับก่อนแตะมิเตอร์</h2><ol><li>รู้ว่าถามอะไรและอ่านเอกสารของเครื่องมือ</li><li>แยกพลังงานและจัดการประจุตกค้างตามโมดูล</li><li>ตรวจว่าไม่มีแรงดันค้างก่อนเลือก Ω / diode / C</li><li>เลือกขาและเน็ตที่ยืนยันแล้ว บันทึกผลกับหน่วย</li><li>ตรวจทางขนานและข้อจำกัดก่อนสรุปชิ้นส่วนเสีย</li></ol><div class="highlight">กล่อง 06 มีป้ายแรงดันสูง กล่อง 07 มีลวดเชื่อมละเอียด ไม่ใช้ฝึกจิ้มบนแผงที่ไม่ทราบเน็ต ใช้บอร์ดฝึกที่ปลอดพลังงานและผู้สอนอนุมัติจุดตรวจเท่านั้น</div>')

