page('เชื่อม R และ C เป็นวงจรอ่านง่าย','<img class="circuit" src="../schematics/02_input_divider.svg"/><p class="small">วงจรสอนจากโครงการนี้ ตัวเลขสมมติ ไม่ใช่ค่าจุดวัดบนกล่องจริง แหล่งภาพแยกจากภาพถ่ายอุปกรณ์</p>','วงจรสอน')
page('แบบฝึก 1 แยกสิ่งที่เห็นจากสิ่งที่เดา','<div class="visual">'+board('ecu-001-2.png',(570,330,280,150),'ภาพ A: marking บนอุปกรณ์และรหัสตำแหน่งมีหน้าที่ต่างกัน')+board('ecu-001-1.png',(650,170,320,340),'ภาพ B: อุปกรณ์หลายชนิดรวมกัน ยังไม่ทราบหน้าที่ทุกตัว')+'</div><p>ทำงานเป็นคู่ อ่านภาพก่อนหยิบมิเตอร์ และแยกคำตอบเป็น “เห็นจริง / สันนิษฐาน / ยังไม่ทราบ”</p>'+table(['โจทย์','บันทึกคำตอบ'],[['1. สิ่งใดในภาพเป็นรหัสบนตัว และสิ่งใดเป็นเลขตำแหน่ง?','____________________________'],['2. ระบุชนิดที่พอบอกได้จากรูปลักษณ์ พร้อมข้อจำกัด','____________________________'],['3. ข้อมูลใดต้องอ่านเพิ่มก่อนกำหนดค่า/ขา?','____________________________'],['4. เลือกโหมดเครื่องมือหนึ่งอย่าง และบอกสิ่งที่มันไม่ยืนยัน','____________________________'],['5. เหตุใดจึงยังไม่เขียน 5 V ลงทุกจุด?','____________________________']])+'<p class="highlight">คำตอบ “ยังไม่ทราบ” พร้อมเหตุผลมีคุณค่า ห้ามเติมชื่อ MCU/driver/EEPROM หรือค่า L/C จากรูปร่างให้ครบช่องโดยไม่มีหลักฐาน</p>','ใบงาน')
page('แบบฝึก 2 ใบบันทึกการวัดบนบอร์ดฝึก','<p>ใช้เฉพาะอุปกรณ์หรือบอร์ดฝึกที่ผู้สอนอนุมัติและจัดการพลังงานแล้ว ไม่ใช้เป็นใบสั่งจ่ายไฟให้ ECU ที่ยังไม่ทราบขา</p>'+table(['ก่อนวัด','บันทึก'],[['ชื่อผู้เรียน / วันที่ / ชิ้นงาน','____________________________'],['เบอร์ชิ้น / reference / แพ็กเกจ','____________________________'],['ภาพจุดตรวจและด้านมอง','____________________________'],['คู่มือ/เกณฑ์และ revision','____________________________'],['แหล่งพลังงานถูกแยกและตรวจประจุตกค้างอย่างไร','____________________________'],['เครื่องมือ รุ่น โหมด และย่าน','____________________________']])+table(['ครั้ง','จุดแดง / จุดดำ หรือคู่ขา','ผลพร้อมหน่วย','คาบอร์ด/แยกขา และเงื่อนไข'],[[i,'____________','____________','___________________'] for i in range(1,5)])+'<h2>สรุปหลักฐาน</h2>'+table(['หัวข้อ','เขียนก่อนตัดสินใจ'],[['ผลพิสูจน์อะไรได้','________________________________'],['สิ่งที่เครื่องมือยังพิสูจน์ไม่ได้','________________________________'],['ทางขนาน/สภาพขั้วต่อ/ข้อสงสัย','________________________________'],['ยืนยันแล้ว / ต้องตรวจเพิ่ม / ส่งต่อ','________________________________']])+'<p class="task">ผู้สอนตรวจความปลอดภัย วิธีเลือกเครื่องมือ และเหตุผลการสรุป ไม่ให้คะแนนจากการเดาชื่ออะไหล่เสียได้ตรงกันอย่างเดียว</p>','ใบงาน')
page('แนวคำตอบและเกณฑ์ตรวจผู้เรียน',table(['คำถามจากบท','แนวตอบ'],[['R 1 kΩ ±5%','950–1,050 Ω ตาม tolerance ของตัวอย่าง ยังต้องคิดความคลาดเคลื่อนเครื่องมือ'],['103 กับ R103 บนแผง','103 บน R ในระบบนั้นคือค่า 10 kΩ ส่วน R103 อาจเป็นเลขตำแหน่ง'],['mΩ กับความต้านทานสาย','สัดส่วนความคลาดเคลื่อนสูง ต้องชดเชย/ใช้วิธีเหมาะสม'],['L บี๊บแปลว่าดีครบหรือไม่','ไม่ครบ ไม่พิสูจน์ช็อตรอบ/อิ่มตัว/การกรอง'],['C 25 V ต้องวัดได้ 25 V?','ไม่ใช่ เป็นพิกัดทนแรงดันของชิ้นตามข้อกำหนด'],['TVS สองทิศ OL ทั้งสองทิศ','ยังตัดสินไม่ได้ ต้องชนิดและวิธีที่เหมาะสม'],['MOSFET วัด V_GS เทียบอะไร','gate เทียบ source ที่ยืนยัน ไม่ใช่ตัวถังเสมอ'],['เปลี่ยนอะไหล่ที่ทรงเดียวกันได้เลย?','ไม่ได้ ต้องตรงหน้าที่ ขา พิกัด และเงื่อนไข']])+'<h2>เกณฑ์ผ่านการฝึก</h2><p>อ่านหน่วยและรหัสได้ • แยกรหัสตำแหน่งกับค่าตัว • เลือกวิธีวัดมีเหตุผล • บอกข้อจำกัดของผล • ไม่ข้ามเงื่อนไขปลอดพลังงาน • สรุปตามหลักฐาน</p><p>หากทำผิดเรื่องขา/กราวด์/พลังงานตกค้าง ให้ทบทวนก่อนเริ่มวัด ไม่แก้ด้วยการสุ่มเปลี่ยนโหมดหรือเพิ่มไฟ</p><p class="small">โจทย์ ตัวเลข และผลคำนวณในเอกสารเป็นตัวอย่างสอน ไม่ใช่ผลซ่อมรถจริงหรือเกณฑ์ที่รับรองใช้กับ ECU ทุกกล่อง</p>','ผู้สอน')

